css:
.ss-check{list-style:none;margin:8px 0 20px;padding:0}
.ss-check__i{display:grid;grid-template-columns:41px minmax(0,1fr);border-bottom:1px solid var(--line)}
.ss-check__m{padding:12px 0 12px 14px;color:var(--accent);font-weight:800;font-size:15px;line-height:1.7}
.ss-check__t{padding:12px 14px;font-size:15px;line-height:1.7;color:var(--body-text)}
.ss-check__h{display:block;color:var(--ink);font-size:15px;margin-bottom:2px}
.ss-check__m::before{content:"\2713"}
.ss-check--cross .ss-check__m{color:var(--bad)}
.ss-check--cross .ss-check__m::before{content:"\2715"}
.ss-check--bullet .ss-check__m::before{content:"\2022"}
.ss-check--dot{margin:0 0 20px}
.ss-check--dot .ss-check__i{grid-template-columns:26px minmax(0,1fr);column-gap:14px;align-items:start;padding:18px 0;border-bottom:0;border-top:1px solid var(--line)}
.ss-check--dot .ss-check__i:last-child{border-bottom:1px solid var(--line)}
.ss-check--dot .ss-check__m{width:26px;height:26px;padding:0;border-radius:999px;background:var(--accent);color:var(--card);font-size:13px;line-height:1;display:flex;align-items:center;justify-content:center}
.ss-check--dot .ss-check__t{padding:0;font-size:15.5px;line-height:1.6;font-weight:600}
